GET /items/1000       ->  200  {"item_id": 1000}

@app.get("/rates")
def rates(code: Annotated[str, Query(pattern="^[A-Z]{3}$")]):
    return {"code": code}

@app.get("/users/{user_id}/items/{item_id}")
def read_user_item(user_id: int, item_id: str,
                   q: str | None = None, short: bool = False):
    item = {"item_id": item_id, "owner_id": user_id}
    if q:
        item["q"] = q
    if not short:
        item["description"] = "A long description"
    return item

